using System;
using System.Collections.Generic;
using System.IO;
using RimTaiName.Pipeline;

namespace RimTaiName.Tests.Pipeline
{
    /// <summary>One row of Fixtures/rules.tsv (generated by Tools/export_rule_fixtures.py).</summary>
    internal sealed class RuleFixture
    {
        private static readonly Lazy<IReadOnlyList<RuleFixture>> AllRows = new Lazy<IReadOnlyList<RuleFixture>>(Load);

        public string Text { get; private set; }

        public NameSpace Ns { get; private set; }

        public string Key { get; private set; }

        /// <summary>special_form() result; empty when the text is not a special form.</summary>
        public string Special { get; private set; }

        public string Zh { get; private set; }

        public bool Valid { get; private set; }

        public bool IsEdgeCase { get; private set; }

        public static IReadOnlyList<RuleFixture> All => AllRows.Value;

        public override string ToString() => $"{Ns}:'{Text}' -> '{Zh}'";

        private static IReadOnlyList<RuleFixture> Load()
        {
            string path = Path.Combine(AppContext.BaseDirectory, "Fixtures", "rules.tsv");
            string[] lines = File.ReadAllLines(path);
            if (lines.Length < 2 || lines[0] != "text\tnamespace\tkey\tspecial\tzh\tvalid\torigin")
                throw new InvalidDataException("unexpected rules.tsv header; rerun Tools/export_rule_fixtures.py");
            var rows = new List<RuleFixture>(lines.Length - 1);
            for (int i = 1; i < lines.Length; i++)
            {
                if (lines[i].Length == 0)
                    continue;
                string[] f = lines[i].Split('\t');
                if (f.Length != 7 || !NameSpaces.TryParse(f[1], out NameSpace ns))
                    throw new InvalidDataException($"rules.tsv line {i + 1} is malformed");
                rows.Add(new RuleFixture
                {
                    Text = f[0],
                    Ns = ns,
                    Key = f[2],
                    Special = f[3],
                    Zh = f[4],
                    Valid = f[5] == "1",
                    IsEdgeCase = f[6] == "edge",
                });
            }
            return rows;
        }
    }
}
